-- 2026-10-05: capítulo editável do Texto Padrão da AEP com a fundamentação
-- técnica e normativa da matriz AIHA (Ergonomia Organizacional), logo após a
-- Metodologia. Já executado via MCP.
-- ROLLBACK: delete from textos_padrao where modulo='aep' and titulo='Avaliação dos Fatores Psicossociais — Matriz de Risco AIHA';
insert into textos_padrao (id_capitulo, modulo, titulo, conteudo, ordem, tipo, slug_fixo, ativo, created_at)
select 'TXT-' || upper(substr(md5(random()::text || 'aiha'), 1, 8)), 'aep', 'Avaliação dos Fatores Psicossociais — Matriz de Risco AIHA', $html$<p style="text-align: justify">Os fatores de risco psicossociais da Ergonomia Organizacional identificados na triagem foram classificados pela <strong>matriz de risco AIHA</strong> (American Industrial Hygiene Association — metodologia <em>A Strategy for Assessing and Managing Occupational Exposures</em>), a mesma ferramenta adotada no inventário de riscos ocupacionais. O nível de risco resulta da combinação de duas dimensões, cada uma graduada em cinco níveis com peso de 0 a 4: a <strong>probabilidade</strong> (grau de exposição, representado pelos sinais observados do fator) e a <strong>severidade</strong> (gravidade potencial do agravo à saúde mental). <strong>Nível de risco = peso da probabilidade × peso da severidade.</strong></p><h3>Fundamentação normativa</h3><ul><li><strong>NR-01, item 1.5.3.1.4</strong> (Portaria MTE nº 1.419/2024): o Gerenciamento de Riscos Ocupacionais abrange os fatores ergonômicos, incluindo os fatores de risco psicossociais relacionados ao trabalho.</li><li><strong>NR-01, item 1.5.4.4.2</strong>: o nível de risco ocupacional é determinado pela combinação da severidade das possíveis lesões ou agravos à saúde com a probabilidade de sua ocorrência.</li><li><strong>NR-01, item 1.5.4.4.3</strong>: a organização seleciona as ferramentas e técnicas de avaliação adequadas ao risco.</li><li><strong>NR-17, itens 17.3.1 e 17.3.1.1</strong>: a Avaliação Ergonômica Preliminar pode utilizar abordagens qualitativas, semiquantitativas, quantitativas ou combinadas.</li><li><strong>NR-17, item 17.3.2</strong>: a Análise Ergonômica do Trabalho deve ser realizada quando a avaliação preliminar indicar necessidade de aprofundamento.</li><li>Referências complementares: Guia de Informações sobre os Fatores de Riscos Psicossociais Relacionados ao Trabalho (MTE), ISO 45003:2021 e ISO 31000.</li></ul><h3>Critérios de aplicação</h3><p style="text-align: justify">Entram na matriz apenas os fatores apontados como presentes na triagem. Sem sinal observado registrado, o fator permanece nos níveis mais baixos (“Não há exposição” × “Pouca importância”), com resultado <strong>Trivial</strong>. A probabilidade é sugerida pela proporção de sinais observados sobre o total de sinais do fator; a severidade parte de um valor padrão por fator. Ambas podem ser ajustadas pelo profissional responsável com base no que foi observado em campo.</p><table><thead><tr><th>Sinais observados</th><th>Probabilidade</th><th>Peso</th></tr></thead><tbody><tr><td>Nenhum</td><td>Não há exposição</td><td>0</td></tr><tr><td>Até 1/3 dos sinais</td><td>Exposição moderada</td><td>2</td></tr><tr><td>Acima de 1/3 até 2/3</td><td>Exposição elevada</td><td>3</td></tr><tr><td>Acima de 2/3</td><td>Exposição elevadíssima</td><td>4</td></tr></tbody></table><table><thead><tr><th>Fator organizacional</th><th>Sinais</th><th>Severidade padrão (peso)</th></tr></thead><tbody><tr><td>Assédio de qualquer natureza no trabalho</td><td>6</td><td>Irreversíveis (3)</td></tr><tr><td>Eventos violentos ou traumáticos</td><td>6</td><td>Irreversíveis (3)</td></tr><tr><td>Falta de suporte / apoio no trabalho</td><td>7</td><td>Severos (2)</td></tr><tr><td>Baixo controle no trabalho / Falta de autonomia</td><td>10</td><td>Severos (2)</td></tr><tr><td>Baixa justiça organizacional</td><td>7</td><td>Severos (2)</td></tr><tr><td>Excesso de demandas no trabalho (Sobrecarga)</td><td>11</td><td>Severos (2)</td></tr><tr><td>Maus relacionamentos no local de trabalho</td><td>9</td><td>Severos (2)</td></tr><tr><td>Má gestão de mudanças organizacionais</td><td>5</td><td>Preocupantes (1)</td></tr><tr><td>Baixa clareza de papel / função</td><td>6</td><td>Preocupantes (1)</td></tr><tr><td>Baixas recompensas e reconhecimento</td><td>8</td><td>Preocupantes (1)</td></tr><tr><td>Baixa demanda no trabalho (Subcarga)</td><td>8</td><td>Preocupantes (1)</td></tr><tr><td>Trabalho em condições de difícil comunicação</td><td>7</td><td>Preocupantes (1)</td></tr><tr><td>Trabalho remoto e isolado</td><td>5</td><td>Preocupantes (1)</td></tr></tbody></table><h3>Matriz de risco</h3><table><thead><tr><th>Probabilidade \ Severidade</th><th>Pouca importância (0)</th><th>Preocupantes (1)</th><th>Severos (2)</th><th>Irreversíveis (3)</th><th>Ameaça (4)</th></tr></thead><tbody><tr><td><strong>Não há exposição (0)</strong></td><td style="background-color: #dcfce7; text-align: center">Trivial (0)</td><td style="background-color: #dcfce7; text-align: center">Trivial (0)</td><td style="background-color: #dcfce7; text-align: center">Trivial (0)</td><td style="background-color: #dcfce7; text-align: center">Trivial (0)</td><td style="background-color: #dcfce7; text-align: center">Trivial (0)</td></tr><tr><td><strong>Exposição a níveis baixos (1)</strong></td><td style="background-color: #dcfce7; text-align: center">Trivial (0)</td><td style="background-color: #ecfccb; text-align: center">Baixo (1)</td><td style="background-color: #ecfccb; text-align: center">Baixo (2)</td><td style="background-color: #fef3c7; text-align: center">Moderado (3)</td><td style="background-color: #fef3c7; text-align: center">Moderado (4)</td></tr><tr><td><strong>Exposição moderada (2)</strong></td><td style="background-color: #dcfce7; text-align: center">Trivial (0)</td><td style="background-color: #ecfccb; text-align: center">Baixo (2)</td><td style="background-color: #fef3c7; text-align: center">Moderado (4)</td><td style="background-color: #fef3c7; text-align: center">Moderado (6)</td><td style="background-color: #fee2e2; text-align: center">Alto (8)</td></tr><tr><td><strong>Exposição elevada (3)</strong></td><td style="background-color: #dcfce7; text-align: center">Trivial (0)</td><td style="background-color: #fef3c7; text-align: center">Moderado (3)</td><td style="background-color: #fef3c7; text-align: center">Moderado (6)</td><td style="background-color: #fee2e2; text-align: center">Alto (9)</td><td style="background-color: #fce7f3; text-align: center">Muito Alto (12)</td></tr><tr><td><strong>Exposição elevadíssima (4)</strong></td><td style="background-color: #dcfce7; text-align: center">Trivial (0)</td><td style="background-color: #fef3c7; text-align: center">Moderado (4)</td><td style="background-color: #fee2e2; text-align: center">Alto (8)</td><td style="background-color: #fce7f3; text-align: center">Muito Alto (12)</td><td style="background-color: #fce7f3; text-align: center">Muito Alto (16)</td></tr></tbody></table><p style="text-align: justify">Faixas: <strong>Trivial</strong> 0 · <strong>Baixo</strong> 1–2 · <strong>Moderado</strong> 3–6 · <strong>Alto</strong> 7–10 · <strong>Muito Alto</strong> ≥ 11. É indicada a Análise Ergonômica do Trabalho (NR-17, 17.3.2) para o setor com ao menos um fator organizacional Alto ou Muito Alto, ou com dois ou mais fatores Moderados.</p><p style="text-align: justify">A AEP constitui triagem preliminar: o nível obtido prioriza fatores e setores, mas não substitui a Análise Ergonômica do Trabalho nem a avaliação por instrumento validado aplicado aos trabalhadores, e deve ser revisto sempre que as condições de trabalho se alterarem.</p>$html$, 2, 'editavel', null, true, now()
where not exists (select 1 from textos_padrao where modulo='aep' and titulo='Avaliação dos Fatores Psicossociais — Matriz de Risco AIHA');
